package cn.lims.report;

import cn.lims.audit.AuditService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.nio.charset.StandardCharsets;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.security.MessageDigest;
import java.time.LocalDateTime;
import java.util.HexFormat;
import java.util.List;
import java.util.Base64;
import org.apache.poi.hwpf.HWPFDocument;
import org.apache.poi.hwpf.extractor.WordExtractor;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.extractor.XWPFWordExtractor;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.font.PDType0Font;
import java.io.File;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1")
public class ReportController {
    private final JdbcTemplate jdbc; private final AuditService audit;
    public ReportController(JdbcTemplate jdbc,AuditService audit){this.jdbc=jdbc;this.audit=audit;}
    @GetMapping("/report-templates") @PreAuthorize("hasAuthority('report:report:view')")
    public List<Template> templates(){return jdbc.query("select t.id,t.code,t.name,t.report_type,t.version_no,t.template_content,t.status,t.version,not exists(select 1 from rpt_report r where r.template_id=t.id and r.deleted=false) from rpt_template t where t.deleted=false order by t.code",(r,n)->{boolean deletable=r.getBoolean(9);return new Template(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getInt(8),deletable,deletable?null:"该模板已被报告引用，不能删除");});}
    @PostMapping("/report-templates") @Transactional @PreAuthorize("hasAuthority('report:template:manage')")
    public Id createTemplate(@Valid @RequestBody TemplateRequest q,Authentication a){Long id=jdbc.queryForObject("insert into rpt_template(code,name,report_type,version_no,template_content,status) values(?,?,?,?,?,?) returning id",Long.class,q.code(),q.name(),q.reportType(),q.versionNo(),q.templateContent(),q.status());audit.record(a,"report:template:create","REPORT_TEMPLATE",id,null,q.toString());return new Id(id);}
    @PutMapping("/report-templates/{id}") @Transactional @PreAuthorize("hasAuthority('report:template:manage')")
    public void updateTemplate(@PathVariable long id,@Valid @RequestBody TemplateRequest q,Authentication a){if(jdbc.update("update rpt_template set code=?,name=?,report_type=?,version_no=?,template_content=?,status=?,updated_at=current_timestamp,version=version+1 where id=? and deleted=false and version=?",q.code(),q.name(),q.reportType(),q.versionNo(),q.templateContent(),q.status(),id,q.version())==0)throw new IllegalArgumentException("模板不存在或已被修改");audit.record(a,"report:template:update","REPORT_TEMPLATE",id,null,q.toString());}
    @DeleteMapping("/report-templates/{id}") @Transactional @PreAuthorize("hasAuthority('report:template:manage')")
    public void deleteTemplate(@PathVariable long id,Authentication a){Boolean referenced=jdbc.queryForObject("select exists(select 1 from rpt_report where template_id=? and deleted=false)",Boolean.class,id);if(Boolean.TRUE.equals(referenced))throw new IllegalArgumentException("该模板已被报告引用，不能删除");if(jdbc.update("update rpt_template set deleted=true,status='DISABLED',updated_at=current_timestamp where id=? and deleted=false",id)==0)throw new IllegalArgumentException("模板不存在");audit.record(a,"report:template:delete","REPORT_TEMPLATE",id,null,"deleted");}
    @PostMapping("/report-templates/import") @PreAuthorize("hasAuthority('report:template:manage')")
    public TemplateImport importTemplate(@RequestBody TemplateFile q){byte[] content=decode(q.fileContentBase64());String name=q.fileName()==null?"导入模板":q.fileName();String lower=name.toLowerCase();try{String text;if(lower.endsWith(".docx")){try(var doc=new XWPFDocument(new ByteArrayInputStream(content));var extractor=new XWPFWordExtractor(doc)){text=extractor.getText();}}else if(lower.endsWith(".doc")){try(var doc=new HWPFDocument(new ByteArrayInputStream(content));var extractor=new WordExtractor(doc)){text=extractor.getText();}}else if(lower.endsWith(".xlsx")||lower.endsWith(".xls")){try(var workbook=WorkbookFactory.create(new ByteArrayInputStream(content))){DataFormatter formatter=new DataFormatter();StringBuilder value=new StringBuilder();for(Sheet sheet:workbook){for(Row row:sheet){for(Cell cell:row){if(value.length()>0&&cell.getColumnIndex()>0)value.append('\t');value.append(formatter.formatCellValue(cell));}value.append('\n');}}text=value.toString();}}else throw new IllegalArgumentException("仅支持 Word 和 Excel 模板文件");String base=name.replaceFirst("(?i)\\.(docx?|xlsx?)$","");return new TemplateImport(base,text.strip());}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("模板文件解析失败");}}
    @GetMapping("/report-templates/{id}/export") @PreAuthorize("hasAuthority('report:report:view')")
    public ResponseEntity<byte[]> exportTemplate(@PathVariable long id,@RequestParam String format){Template t=templates().stream().filter(x->x.id()==id).findFirst().orElseThrow(()->new IllegalArgumentException("模板不存在"));try{byte[] data;String fileName;MediaType type;if("word".equalsIgnoreCase(format)){try(var doc=new XWPFDocument();var out=new ByteArrayOutputStream()){for(String line:t.templateContent().split("\\R",-1)){XWPFParagraph paragraph=doc.createParagraph();paragraph.createRun().setText(line);}doc.write(out);data=out.toByteArray();}fileName=t.name()+"_"+t.versionNo()+".docx";type=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");}else if("excel".equalsIgnoreCase(format)){try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){Sheet sheet=workbook.createSheet("模板内容");int index=0;for(String line:t.templateContent().split("\\R",-1))sheet.createRow(index++).createCell(0).setCellValue(line);workbook.write(out);data=out.toByteArray();}fileName=t.name()+"_"+t.versionNo()+".xlsx";type=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");}else throw new IllegalArgumentException("导出格式仅支持 word 或 excel");HttpHeaders headers=new HttpHeaders();headers.setContentDisposition(ContentDisposition.attachment().filename(fileName,StandardCharsets.UTF_8).build());headers.setContentType(type);return ResponseEntity.ok().headers(headers).contentLength(data.length).body(data);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("模板导出失败");}}
    @GetMapping("/reports") @PreAuthorize("hasAuthority('report:report:view')")
    public List<ReportRow> reports(){return jdbc.query("select r.id,r.report_no,r.report_type,r.customer_name,r.template_id,coalesce(t.name,''),r.title,r.status,coalesce(u.display_name,''),r.review_comment,r.approval_comment,r.updated_at,r.version from rpt_report r left join rpt_template t on t.id=r.template_id left join sys_user u on u.id=r.author_id where r.deleted=false order by r.id desc",(x,n)->new ReportRow(x.getLong(1),x.getString(2),x.getString(3),x.getString(4),nullable(x,5),x.getString(6),x.getString(7),x.getString(8),x.getString(9),x.getString(10),x.getString(11),x.getObject(12,LocalDateTime.class),x.getInt(13)));}
    @GetMapping("/reports/{id}") @PreAuthorize("hasAuthority('report:report:view')")
    public ReportDetail detail(@PathVariable long id){return jdbc.queryForObject("select id,report_no,report_type,customer_name,template_id,title,content,status,file_hash,archive_location,version from rpt_report where id=? and deleted=false",(x,n)->new ReportDetail(x.getLong(1),x.getString(2),x.getString(3),x.getString(4),nullable(x,5),x.getString(6),x.getString(7),x.getString(8),x.getString(9),x.getString(10),x.getInt(11)),id);}
    @PostMapping("/reports") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public Id create(@Valid @RequestBody ReportRequest q,Authentication a){String no="BG"+System.currentTimeMillis();Long id=jdbc.queryForObject("insert into rpt_report(report_no,report_type,customer_name,template_id,title,content,author_id) values(?,?,?,?,?,?,?) returning id",Long.class,no,q.reportType(),q.customerName(),q.templateId(),q.title(),q.content(),userId(a));audit.record(a,"report:report:create","REPORT",id,null,no);return new Id(id);}
    @PutMapping("/reports/{id}") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public void update(@PathVariable long id,@Valid @RequestBody ReportRequest q,Authentication a){if(jdbc.update("update rpt_report set report_type=?,customer_name=?,template_id=?,title=?,content=?,updated_at=current_timestamp,version=version+1 where id=? and status='DRAFT' and version=?",q.reportType(),q.customerName(),q.templateId(),q.title(),q.content(),id,q.version())==0)throw new IllegalArgumentException("仅编制中的报告可修改，或数据已被修改");audit.record(a,"report:report:update","REPORT",id,null,q.toString());}
    @PostMapping("/reports/{id}/preview") @PreAuthorize("hasAuthority('report:report:view')")
    public Preview preview(@PathVariable long id){ReportDetail r=detail(id);String templateName=null;String tpl;if(r.templateId()==null){tpl="报告编号：{{reportNo}}\n委托单位：{{customerName}}\n{{content}}";}else{var template=jdbc.queryForMap("select name,template_content from rpt_template where id=? and deleted=false",r.templateId());templateName=String.valueOf(template.get("name"));tpl=String.valueOf(template.get("template_content"));}return new Preview(render(r,tpl),r.templateId(),templateName);}
    @PutMapping("/reports/{id}/template") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public Preview selectTemplate(@PathVariable long id,@RequestBody TemplateSelection q,Authentication a){if(q.templateId()!=null){Boolean exists=jdbc.queryForObject("select exists(select 1 from rpt_template where id=? and deleted=false and status='ENABLED')",Boolean.class,q.templateId());if(!Boolean.TRUE.equals(exists))throw new IllegalArgumentException("所选模板不存在或未启用");}if(jdbc.update("update rpt_report set template_id=?,updated_at=current_timestamp,version=version+1 where id=? and deleted=false",q.templateId(),id)==0)throw new IllegalArgumentException("报告不存在");audit.record(a,"report:report:template","REPORT",id,null,String.valueOf(q.templateId()));return preview(id);}
    @GetMapping("/reports/{id}/export") @PreAuthorize("hasAuthority('report:report:view')")
    public ResponseEntity<byte[]> exportReport(@PathVariable long id,@RequestParam String format){ReportDetail r=detail(id);if(r.templateId()==null)throw new IllegalArgumentException("报告未选择模板，不能导出");String tpl=jdbc.queryForObject("select template_content from rpt_template where id=? and deleted=false",String.class,r.templateId());String content=render(r,tpl);try{byte[] data;String extension;MediaType type;if("word".equalsIgnoreCase(format)){try(var doc=new XWPFDocument();var out=new ByteArrayOutputStream()){for(String line:content.split("\\R",-1)){XWPFParagraph p=doc.createParagraph();p.createRun().setText(line);}doc.write(out);data=out.toByteArray();}extension="docx";type=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");}else if("excel".equalsIgnoreCase(format)){try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){Sheet sheet=workbook.createSheet("报告内容");int index=0;for(String line:content.split("\\R",-1))sheet.createRow(index++).createCell(0).setCellValue(line);workbook.write(out);data=out.toByteArray();}extension="xlsx";type=MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");}else if("pdf".equalsIgnoreCase(format)){data=createPdf(content);extension="pdf";type=MediaType.APPLICATION_PDF;}else throw new IllegalArgumentException("导出格式仅支持 word、excel 或 pdf");String fileName=r.reportNo()+"_"+r.title()+"."+extension;HttpHeaders headers=new HttpHeaders();headers.setContentDisposition(ContentDisposition.attachment().filename(fileName,StandardCharsets.UTF_8).build());headers.setContentType(type);return ResponseEntity.ok().headers(headers).contentLength(data.length).body(data);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("报告导出失败");}}
    @PostMapping("/reports/{id}/submit") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public void submit(@PathVariable long id,Authentication a){move(id,"REVIEWING","status='DRAFT'","submitted_at=current_timestamp",a,"submit");}
    @PostMapping("/reports/{id}/review") @Transactional @PreAuthorize("hasAuthority('report:report:review')")
    public void review(@PathVariable long id,@RequestBody Decision q,Authentication a){Long reviewer=userId(a);String target=q.approved()?"ARCHIVED":"DRAFT";int changed=q.approved()?jdbc.update("update rpt_report set status='ARCHIVED',reviewer_id=?,review_comment=?,reviewed_at=current_timestamp,archived_at=current_timestamp,updated_at=current_timestamp,version=version+1 where id=? and status='REVIEWING'",reviewer,q.comment(),id):jdbc.update("update rpt_report set status='DRAFT',reviewer_id=?,review_comment=?,reviewed_at=current_timestamp,submitted_at=null,archived_at=null,updated_at=current_timestamp,version=version+1 where id=? and status='REVIEWING'",reviewer,q.comment(),id);if(changed==0)throw new IllegalArgumentException("仅待审核报告可以审批通过或退回");audit.record(a,"report:report:review","REPORT",id,"REVIEWING",target);}
    @PostMapping("/reports/{id}/approve") @Transactional @PreAuthorize("hasAuthority('report:report:approve')")
    public void approve(@PathVariable long id,@RequestBody Decision q,Authentication a){var row=jdbc.queryForMap("select author_id,reviewer_id,report_no,customer_name,content from rpt_report where id=? and status='PENDING_APPROVAL'",id);Long uid=userId(a);if(uid.equals(row.get("author_id"))||uid.equals(row.get("reviewer_id")))throw new IllegalArgumentException("批准人必须与编制人、审核人分离");String target=q.approved()?"APPROVED":"REJECTED";String hash=q.approved()?sha(row.toString()):null;if(jdbc.update("update rpt_report set status=?,approver_id=?,approval_comment=?,approved_at=current_timestamp,file_hash=?,updated_at=current_timestamp where id=? and status='PENDING_APPROVAL'",target,uid,q.comment(),hash,id)==0)throw new IllegalArgumentException("仅待批准报告可处理");audit.record(a,"report:report:approve","REPORT",id,"PENDING_APPROVAL",target);}
    @PostMapping("/report-versions/{id}/distributions") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public void distribute(@PathVariable long id,@RequestBody Action q,Authentication a){if(jdbc.update("update rpt_report set status='DISTRIBUTED',distributed_at=current_timestamp,updated_at=current_timestamp where id=? and status='APPROVED'",id)==0)throw new IllegalArgumentException("仅已批准报告可发放");audit.record(a,"report:report:distribute","REPORT",id,"APPROVED",q.comment());}
    @PostMapping("/report-versions/{id}/archive") @Transactional @PreAuthorize("hasAuthority('report:report:manage')")
    public void archive(@PathVariable long id,@RequestBody Action q,Authentication a){if(jdbc.update("update rpt_report set status='ARCHIVED',archived_at=current_timestamp,archive_location=?,updated_at=current_timestamp where id=? and status='DISTRIBUTED'",q.comment(),id)==0)throw new IllegalArgumentException("仅已发放报告可归档");audit.record(a,"report:report:archive","REPORT",id,"DISTRIBUTED",q.comment());}
    @PostMapping("/reports/{id}/void") @Transactional @PreAuthorize("hasAuthority('report:report:approve')")
    public void voidReport(@PathVariable long id,@RequestBody Action q,Authentication a){if(jdbc.update("update rpt_report set status='VOID',updated_at=current_timestamp where id=? and status in('APPROVED','DISTRIBUTED')",id)==0)throw new IllegalArgumentException("当前报告状态不能作废");audit.record(a,"report:report:void","REPORT",id,null,q.comment());}
    @GetMapping("/reports/summary") @PreAuthorize("hasAuthority('report:report:view')")
    public Summary summary(){return jdbc.queryForObject("select count(*) filter(where status='DRAFT'),count(*) filter(where status='REVIEWING'),count(*) filter(where status='ARCHIVED') from rpt_report where deleted=false",(r,n)->new Summary(r.getLong(1),r.getLong(2),r.getLong(3)));}
    private void move(long id,String target,String condition,String extra,Authentication a,String action){if(jdbc.update("update rpt_report set status=?,"+extra+",updated_at=current_timestamp where id=? and "+condition,target,id)==0)throw new IllegalArgumentException("报告状态不允许此操作");audit.record(a,"report:report:"+action,"REPORT",id,null,target);}
    private Long userId(Authentication a){return jdbc.queryForObject("select id from sys_user where username=? and deleted=false",Long.class,a.getName());}
    private static String render(ReportDetail r,String tpl){return tpl.replace("{{reportNo}}",r.reportNo()).replace("{{customerName}}",r.customerName()).replace("{{content}}",r.content()==null?"":r.content()).replace("{{title}}",r.title()==null?"":r.title()).replace("{{reportType}}",r.reportType()==null?"":r.reportType());}
    private static byte[] createPdf(String content)throws Exception{try(var document=new PDDocument();var out=new ByteArrayOutputStream()){PDType0Font font=PDType0Font.load(document,new File("C:/Windows/Fonts/simhei.ttf"));PDPage page=new PDPage(PDRectangle.A4);document.addPage(page);PDPageContentStream stream=new PDPageContentStream(document,page);float y=PDRectangle.A4.getHeight()-55;for(String source:content.split("\\R",-1)){String line=source;do{int end=Math.min(line.length(),45);String part=line.substring(0,end);if(y<55){stream.close();page=new PDPage(PDRectangle.A4);document.addPage(page);stream=new PDPageContentStream(document,page);y=PDRectangle.A4.getHeight()-55;}stream.beginText();stream.setFont(font,12);stream.newLineAtOffset(50,y);stream.showText(part);stream.endText();y-=20;line=line.substring(end);}while(!line.isEmpty());if(source.isEmpty())y-=20;}stream.close();document.save(out);return out.toByteArray();}}
    private static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static byte[] decode(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("请选择模板文件");try{String payload=value.contains(",")?value.substring(value.indexOf(',')+1):value;return Base64.getDecoder().decode(payload);}catch(Exception e){throw new IllegalArgumentException("模板文件内容格式错误");}}
    private static Long nullable(java.sql.ResultSet r,int i)throws java.sql.SQLException{long v=r.getLong(i);return r.wasNull()?null:v;}
    public record Id(Long id){} public record Template(long id,String code,String name,String reportType,String versionNo,String templateContent,String status,int version,boolean deletable,String deleteDisabledReason){}
    public record TemplateRequest(@NotBlank String code,@NotBlank String name,@NotBlank String reportType,@NotBlank String versionNo,String templateContent,@NotBlank String status,int version){}
    public record TemplateFile(String fileName,String fileContentBase64){} public record TemplateImport(String name,String templateContent){}
    public record ReportRow(long id,String reportNo,String reportType,String customerName,Long templateId,String templateName,String title,String status,String authorName,String reviewComment,String approvalComment,LocalDateTime updatedAt,int version){}
    public record ReportDetail(long id,String reportNo,String reportType,String customerName,Long templateId,String title,String content,String status,String fileHash,String archiveLocation,int version){}
    public record ReportRequest(@NotBlank String reportType,@NotBlank String customerName,Long templateId,@NotBlank String title,String content,int version){}
    public record Decision(boolean approved,String comment){} public record Action(String comment){} public record Preview(String content,Long templateId,String templateName){} public record TemplateSelection(Long templateId){}
    public record Summary(long drafts,long reviewing,long archived){}
}
